<?php namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; class StoreOrderRequest extends FormRequest { public function authorize(): bool { return $this->user()?->role === 'student'; } public function rules(): array { return ['stall_id' => ['required', 'exists:stalls,id'], 'pickup_time' => ['required', 'string', 'max:50'], 'food_item_id' => ['required', 'exists:food_items,id'], 'quantity' => ['required', 'integer', 'min:1', 'max:20']]; } }